(function () {
	'use strict';

	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	var STORAGE_KEY = 'todos-vanillajs';

	var util = {
		uuid: function () {
			return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
				var r = (Math.random() * 16) | 0;
				var v = c === 'x' ? r : (r & 0x3) | 0x8;
				return v.toString(16);
			});
		},

		store: function (namespace, data) {
			if (arguments.length > 1) {
				return localStorage.setItem(namespace, JSON.stringify(data));
			} else {
				var store = localStorage.getItem(namespace);
				return (store && JSON.parse(store)) || [];
			}
		},

		pluralize: function (count, word) {
			return count === 1 ? word : word + 's';
		}
	};

	var model = {
		todos: [],

		init: function () {
			this.todos = util.store(STORAGE_KEY);
		},

		bumpId: function () {
			return util.uuid();
		},

		add: function (title) {
			this.todos.push({
				id: this.bumpId(),
				title: title.trim(),
				completed: false
			});
			this.commit();
		},

		edit: function (id, title) {
			this.todos.forEach(function (todo) {
				if (todo.id === id) {
					todo.title = title.trim();
				}
			});
			this.commit();
		},

		remove: function (id) {
			this.todos = this.todos.filter(function (todo) {
				return todo.id !== id;
			});
			this.commit();
		},

		toggle: function (id) {
			this.todos.forEach(function (todo) {
				if (todo.id === id) {
					todo.completed = !todo.completed;
				}
			});
			this.commit();
		},

		toggleAll: function (completed) {
			this.todos.forEach(function (todo) {
				todo.completed = completed;
			});
			this.commit();
		},

		clearCompleted: function () {
			this.todos = this.todos.filter(function (todo) {
				return !todo.completed;
			});
			this.commit();
		},

		commit: function () {
			util.store(STORAGE_KEY, this.todos);
		}
	};

	var view = {
		elements: {},

		init: function () {
			this.elements.main = document.querySelector('.main');
			this.elements.toggleAll = document.querySelector('.toggle-all');
			this.elements.todoList = document.querySelector('.todo-list');
			this.elements.footer = document.querySelector('.footer');
			this.elements.count = document.querySelector('.todo-count');
			this.elements.clearCompleted = document.querySelector('.clear-completed');
			this.elements.newTodo = document.querySelector('.new-todo');
			this.elements.filters = document.querySelectorAll('.filters a');
		},

		render: function (todos, activeFilter) {
			var self = this;
			var filteredTodos = todos.filter(function (todo) {
				if (activeFilter === 'active') return !todo.completed;
				if (activeFilter === 'completed') return todo.completed;
				return true;
			});

			var allCompleted = todos.length > 0 && todos.every(function (todo) {
				return todo.completed;
			});

			var activeCount = todos.filter(function (todo) {
				return !todo.completed;
			}).length;

			var completedCount = todos.length - activeCount;

			// Show/hide main and footer
			this.elements.main.style.display = todos.length > 0 ? 'block' : 'none';
			this.elements.footer.style.display = todos.length > 0 ? 'block' : 'none';

			// Toggle-all state
			this.elements.toggleAll.checked = allCompleted;

			// Count
			this.elements.count.innerHTML = '<strong>' + activeCount + '</strong> ' +
				util.pluralize(activeCount, 'item') + ' left';

			// Clear completed visibility
			this.elements.clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

			// Filter links
			this.elements.filters.forEach(function (link) {
				if (link.getAttribute('href') === '#/' + activeFilter) {
					link.classList.add('selected');
				} else if (activeFilter === '' && link.getAttribute('href') === '#/') {
					link.classList.add('selected');
				} else {
					link.classList.remove('selected');
				}
			});

			// Build todo list
			this.elements.todoList.innerHTML = '';
			filteredTodos.forEach(function (todo) {
				var li = document.createElement('li');
				li.setAttribute('data-id', todo.id);
				if (todo.completed) li.classList.add('completed');

				li.innerHTML =
					'<div class="view">' +
					'<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
					'<label>' + self.escapeHtml(todo.title) + '</label>' +
					'<button class="destroy"></button>' +
					'</div>' +
					'<input class="edit" value="' + self.escapeHtml(todo.title) + '">';

				self.elements.todoList.appendChild(li);
			});
		},

		escapeHtml: function (str) {
			var div = document.createElement('div');
			div.appendChild(document.createTextNode(str));
			return div.innerHTML;
		}
	};

	var controller = {
		activeFilter: '',

		init: function () {
			model.init();
			view.init();

			var self = this;

			// New todo input
			view.elements.newTodo.addEventListener('keyup', function (e) {
				if (e.keyCode === ENTER_KEY) {
					self.addTodo();
				}
			});

			// Toggle all
			view.elements.toggleAll.addEventListener('change', function () {
				model.toggleAll(this.checked);
				self.render();
			});

			// Clear completed
			view.elements.clearCompleted.addEventListener('click', function () {
				model.clearCompleted();
				self.render();
			});

			// Delegate todo list events
			view.elements.todoList.addEventListener('click', function (e) {
				var target = e.target;
				var li = target.closest('li');
				if (!li) return;
				var id = li.getAttribute('data-id');

				if (target.classList.contains('toggle')) {
					model.toggle(id);
					self.render();
				} else if (target.classList.contains('destroy')) {
					model.remove(id);
					self.render();
				}
			});

			// Double-click to edit
			view.elements.todoList.addEventListener('dblclick', function (e) {
				var target = e.target;
				if (target.tagName !== 'LABEL') return;
				var li = target.closest('li');
				if (!li) return;
				li.classList.add('editing');
				var editInput = li.querySelector('.edit');
				editInput.focus();
			});

			// Edit input events
			view.elements.todoList.addEventListener('keyup', function (e) {
				var target = e.target;
				if (!target.classList.contains('edit')) return;
				var li = target.closest('li');
				if (!li) return;
				var id = li.getAttribute('data-id');

				if (e.keyCode === ENTER_KEY) {
					self.commitEdit(id, target);
				} else if (e.keyCode === ESCAPE_KEY) {
					target.value = target.getAttribute('value');
					li.classList.remove('editing');
				}
			});

			view.elements.todoList.addEventListener('blur', function (e) {
				var target = e.target;
				if (!target.classList.contains('edit')) return;
				var li = target.closest('li');
				if (!li) return;
				var id = li.getAttribute('data-id');
				self.commitEdit(id, target);
			}, true);

			// Hash change for routing
			window.addEventListener('hashchange', function () {
				self.onHashChange();
			});

			this.onHashChange();
			this.render();
		},

		commitEdit: function (id, input) {
			var li = input.closest('li');
			var title = input.value.trim();
			if (title) {
				model.edit(id, title);
			} else {
				model.remove(id);
			}
			li.classList.remove('editing');
			this.render();
		},

		addTodo: function () {
			var title = view.elements.newTodo.value.trim();
			if (!title) return;
			model.add(title);
			view.elements.newTodo.value = '';
			this.render();
		},

		onHashChange: function () {
			var hash = window.location.hash || '#/';
			if (hash === '#/active') {
				this.activeFilter = 'active';
			} else if (hash === '#/completed') {
				this.activeFilter = 'completed';
			} else {
				this.activeFilter = '';
			}
			this.render();
		},

		render: function () {
			view.render(model.todos, this.activeFilter);
		}
	};

	controller.init();
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

Given('the app is loaded', function () {
  // App is loaded by world.js Before hook
  expect(this.document.querySelector('.todoapp')).to.not.be.null;
});

When('I type {string} in the new todo input and press Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { keyCode: 13, bubbles: true }));
});

Then('I should see {int} todo(s) in the list', function (count) {
  const todos = this.document.querySelectorAll('.todo-list li');
  expect(todos.length).to.equal(count);
});

Then('the todo {string} should be visible', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  expect(found).to.be.true;
});

Then('the main section should be hidden', function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).to.equal('none');
});

Then('the main section should be visible', function () {
  const main = this.document.querySelector('.main');
  expect(main.style.display).to.equal('block');
});

Then('the footer should be hidden', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).to.equal('none');
});

Then('the footer should be visible', function () {
  const footer = this.document.querySelector('.footer');
  expect(footer.style.display).to.equal('block');
});

Then('the count should show {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  expect(count.textContent).to.include(text);
});

When('I click the toggle for the first todo', function () {
  const toggle = this.document.querySelector('.todo-list li .toggle');
  toggle.click();
});

Then('the first todo should be completed', function () {
  const li = this.document.querySelector('.todo-list li');
  expect(li.classList.contains('completed')).to.be.true;
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  toggleAll.click();
});

Then('all todos should be completed', function () {
  const todos = this.document.querySelectorAll('.todo-list li');
  todos.forEach(li => {
    expect(li.classList.contains('completed')).to.be.true;
  });
});

When('I click the clear completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.click();
});

When('I click the destroy button for the first todo', function () {
  const btn = this.document.querySelector('.todo-list li .destroy');
  btn.click();
});

When('I double-click the label of the first todo', function () {
  const label = this.document.querySelector('.todo-list li label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

Then('the first todo should be in editing mode', function () {
  const li = this.document.querySelector('.todo-list li');
  expect(li.classList.contains('editing')).to.be.true;
});

When('I clear the edit input and type {string} and press Enter', function (title) {
  const input = this.document.querySelector('.todo-list li.editing .edit');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { keyCode: 13, bubbles: true }));
});

When('I clear the edit input and press Enter', function () {
  const input = this.document.querySelector('.todo-list li.editing .edit');
  input.value = '';
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { keyCode: 13, bubbles: true }));
});

When('I clear the edit input and type {string} and press Escape', function (title) {
  const input = this.document.querySelector('.todo-list li.editing .edit');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { keyCode: 27, bubbles: true }));
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('the page is reloaded', function () {
  this.disposeApp();
  this.loadApp();
});

Then('the toggle-all checkbox should be checked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  expect(toggleAll.checked).to.be.true;
});

Then('the toggle-all checkbox should be unchecked', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  expect(toggleAll.checked).to.be.false;
});

