async disposeApp() {
  const w = this.window;
  if (!w) return;
  // Snapshot localStorage before destroying the window so a subsequent loadApp() can
  // restore it — happy-dom windows have isolated storage, but persistence scenarios
  // need data to survive a reload.
  try {
    for (let i = 0; i < w.localStorage.length; i++) {
      const key = w.localStorage.key(i);
      this._persistedStorage[key] = w.localStorage.getItem(key);
    }
  } catch (_) { /* ignore */ }
  this.window = undefined;
